from pathlib import Path
import json,hashlib,base64,shutil,html
from PIL import Image
R=Path('D:/AI-Yang.cn/HomeDesign');OUT=R/'09_delivery/v20-complete';PH=R/'07_renders/v20-complete-photographic';TOUR=R/'09_delivery/vr-tour-v07'
TOUR.mkdir(exist_ok=True);(TOUR/'全景原图').mkdir(exist_ok=True);(OUT/'photos').mkdir(exist_ok=True)
def load(p):return json.loads((R/p).read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
