labels={'living':'客厅','dining':'餐厅','balcony':'阳台','entry':'门厅'};images=[];scenes=[]
positions={'living':[1800,4500],'dining':[770,8850],'balcony':[2050,850],'entry':[635,10100]};views={'living':[-50,-10,70],'dining':[-25,-15,75],'balcony':[-8,-26,60],'entry':[-90,-12,95]}
for key,label in labels.items():
    for kind in ['photo','pano']:
        source=PH/f'{key}-{kind}.png';assert source.read_bytes()[:8]==b'\x89PNG\r\n\x1a\n'
        with Image.open(source) as im:im.verify()
        with Image.open(source) as im:w,h=im.size
        if kind=='pano':assert w==h*2
        target=OUT/'photos'/f'{key}.png' if kind=='photo' else TOUR/'全景原图'/f'{key}.png';shutil.copy2(source,target)
        images.append(dict(id=key,kind=kind,path=source.relative_to(R).as_posix(),deliveryPath=target.relative_to(R).as_posix(),resolution=[w,h],sha256=sha(source)))
        if kind=='pano':
            y,p,f=views[key];scenes.append(dict(id=key,label=label,image=source.relative_to(R).as_posix(),imageData='data:image/png;base64,'+base64.b64encode(source.read_bytes()).decode(),positionPlanMm=positions[key],eyeHeightMm=1600,initialYawDeg=y,initialPitchDeg=p,initialFovDeg=f,headingAtImageCenterDeg=0,imageWidth=w,imageHeight=h,downloadName=label+'-v20实装完整版-360全景.png'))
